def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    req_sum = WATER_REQ
    dangerous_prev = 0.0
    eric_like_bid = None

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            req_sum += float(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                bid = float(bid)
                prev_bids.append(bid)
                if bid > dangerous_prev:
                    dangerous_prev = bid
                if oid == 'Eric':
                    eric_like_bid = bid

    scarcity = req_sum / max(supply, 1.0)
    tight = supply <= 17.0 or scarcity >= 2.2
    very_tight = supply <= 15.5 or scarcity >= 2.8

    if not alive:
        return max(0.0, min(budget, 18.0))

    if hp <= 2 or no_water >= 2:
        target = 96.0
        if prev_bids:
            target = max(target, dangerous_prev + 2.0)
        if very_tight:
            target += 10.0
        return max(0.0, min(budget, target))

    if hp <= 4 or no_water >= 1:
        anchor = 78.0
        if eric_like_bid is not None:
            anchor = max(anchor, eric_like_bid + 3.0)
        elif prev_bids:
            anchor = max(anchor, min(dangerous_prev + 2.0, 95.0))
        if tight:
            anchor += 6.0
        return max(0.0, min(budget, anchor))

    if day <= 2 and hp >= 8 and no_water == 0:
        base = 24.0 if not tight else 34.0
        return max(0.0, min(budget, base))

    if eric_like_bid is not None:
        base = eric_like_bid + 1.5
    elif prev_bids:
        sorted_bids = sorted(prev_bids)
        idx = int(len(sorted_bids) - 1)
        base = sorted_bids[int(idx)] * 0.72
    else:
        base = 42.0

    if dangerous_prev > 180.0:
        base = min(base, 58.0)
    elif dangerous_prev > 120.0:
        base = min(max(base, 52.0), 68.0)
    else:
        base = max(base, 46.0)

    if tight:
        base += 6.0
    if very_tight:
        base += 6.0
    if hp >= 8 and no_water == 0 and not tight:
        base -= 6.0

    spend_cap = budget
    if hp >= 7 and no_water == 0:
        spend_cap = min(spend_cap, DAILY_SALARY * 0.95)
    elif hp >= 5:
        spend_cap = min(spend_cap, DAILY_SALARY * 1.15)
    else:
        spend_cap = min(spend_cap, DAILY_SALARY * 1.45)

    bid = max(0.0, min(spend_cap, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Determine highest previous bid among alive opponents
    highest_prev = 0.0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None and isinstance(bid, (int, float)):
            if bid > highest_prev:
                highest_prev = bid

    hp = my_status['hp']
    budget = my_status['budget']

    # Calculate survival bid based on water requirement and supply
    supply = day_context['supply']
    # Ensure integer index for any list usage (none here, but safe)
    # Compute a baseline bid
    if hp <= 2:
        # Desperate: bid up to 90% of salary plus maybe beat high previous
        target = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
        return min(budget, target)
    elif hp <= 4:
        # Moderate risk: try to win if previous high is not extreme
        if highest_prev >= DAILY_SALARY * 1.2:
            # Too expensive, conserve
            return min(budget, DAILY_SALARY * 0.5)
        else:
            target = max(DAILY_SALARY * 0.6, highest_prev + 1.5)
            return min(budget, target)
    else:
        # Healthy: bid conservatively
        if highest_prev == 0:
            return min(budget, DAILY_SALARY * 0.4)
        if highest_prev >= DAILY_SALARY * 1.0:
            return min(budget, DAILY_SALARY * 0.3)
        return min(budget, max(DAILY_SALARY * 0.45, highest_prev + 1.0))
